package com.bank.pricing;

import java.lang.invoke.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class MemoryFenceDemo {
    private static final Logger LOG = Logger.getLogger("Pricing");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        SettlementPublisher box = new SettlementPublisher();
        Thread consumer = new Thread(new SettlementConsumer(box, LOG), "settlement");
        consumer.start();

        // Pricing thread computes then publishes with a release fence.
        box.publish(new BigDecimal("50000"));
        consumer.join();
        LOG.info("demo complete: consumer saw the fully computed amount");
    }
}

// ─── Would be in publish/SettlementPublisher.java ───
class SettlementPublisher {
    private BigDecimal amount = BigDecimal.ZERO;   // plain (non-volatile) data field
    private boolean ready = false;                 // flag accessed via VarHandle
    private static final VarHandle READY;
    static {
        try {
            READY = MethodHandles.lookup()
                .findVarHandle(SettlementPublisher.class, "ready", boolean.class);
        } catch (ReflectiveOperationException e) { throw new ExceptionInInitializerError(e); }
    }

    void publish(BigDecimal computed) {
        this.amount = computed;        // WRITE the data (ordinary store)
        VarHandle.releaseFence();      // StoreStore+LoadStore: publish data BEFORE flag
        READY.setVolatile(this, true); // set flag; release semantics guarantee visibility
    }

    boolean isReady()      { return (boolean) READY.getVolatile(this); } // acquire read
    BigDecimal readAmount() { return amount; }                           // read after acquire
}

// ─── Would be in consume/SettlementConsumer.java ───
class SettlementConsumer implements Runnable {
    private final SettlementPublisher box;
    private final Logger log;
        SettlementConsumer(SettlementPublisher box, Logger log) { this.box = box;
        this.log = log; }
    @Override public void run() {
        while (!box.isReady()) { Thread.onSpinWait(); }  // acquire read of flag in loop
        VarHandle.acquireFence();                        // LoadLoad+LoadStore: read fresh data
        BigDecimal amt = box.readAmount();               // guaranteed 50000, never 0
        log.info(() -> "consumer read settlement amount = Rs." + amt);
    }
}
