package com.bank.pricing.publish;

import org.junit.jupiter.api.RepeatedTest;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

class FencePublishTest {
    @RepeatedTest(1000)   // repeat to stress ordering on multi-core
    void consumerNeverSeesStaleAmount() throws Exception {
        SettlementPublisher box = new SettlementPublisher();
        Thread t = new Thread(() -> {
            while (!box.isReady()) { Thread.onSpinWait(); }
            assertEquals(new BigDecimal("50000"), box.readAmount());  // never 0
        });
        t.start();
        box.publish(new BigDecimal("50000"));
        t.join();
    }
}
